func process(p *int) {
	defer fmt.Println("done", *p)
	*p += 5
}

func main() {
	n := 1
	process(&n)
	fmt.Println(n)
}

func lookup(code string) *int {
	if code == "A" {
		n := 7
		return &n
	}
	return nil
}

func main() {
	fmt.Println(*lookup("A"))
	fmt.Println(*lookup("B"))
}

func firstEven(nums []int) (int, bool) {
	result, ok := 0, false
	for _, n := range nums {
		if n%2 == 0 {
			result, ok := n, true
			fmt.Println("found", result, ok)
			break
		}
	}
	return result, ok
}

func main() {
	fmt.Println(firstEven([]int{3, 4, 5}))
}

